public sealed class Validity
{
    public Time NotBefore { get; set; }
    public Time NotAfter { get; set; }

    public void Encode(Asn1Writer writer) => Encode(writer, DefaultTag);

    public void Encode(Asn1Writer writer, Asn1Tag tag)
    {
        using (writer.EnterSequence(tag))
        {
            NotBefore.Encode(writer);
            NotAfter.Encode(writer);
        }
    }

    public static Validity Decode(Asn1Reader reader) => Decode(reader, DefaultTag);

    public static Validity Decode(Asn1Reader reader, Asn1Tag tag)
    {
        using (reader.EnterSequence(tag))
        {
            var value = new Validity();
            value.NotBefore = Asn1Kit.Modern.PKIX1Explicit2009.Time.Decode(reader);
            value.NotAfter = Asn1Kit.Modern.PKIX1Explicit2009.Time.Decode(reader);
            reader.ThrowIfNotEmpty();
            return value;
        }
    }

    public static Asn1Tag DefaultTag { get; } = Asn1Tag.Sequence;
}

public enum TimeKind
{
    UtcTime,
    GeneralTime,
}

public sealed class Time
{
    public TimeKind Kind { get; private set; }
    public DateTimeOffset Value { get; private set; }

    public static Time FromUtcTime(DateTimeOffset utcTime) => new Time
    {
        Kind = TimeKind.UtcTime,
        Value = utcTime,
    };

    public static Time FromGeneralTime(DateTimeOffset generalTime) => new Time
    {
        Kind = TimeKind.GeneralTime,
        Value = generalTime,
    };

    public override string ToString()
    {
        return Kind switch
        {
            TimeKind.UtcTime => Asn1Formatting.Format(Value),
            TimeKind.GeneralTime => Asn1Formatting.Format(Value),
            _ => "<unset>",
        };
    }

    public void Encode(Asn1Writer writer)
    {
        switch (Kind)
        {
            case TimeKind.UtcTime:
                writer.WriteTime(Asn1Tag.UtcTime, Value, Asn1TimeForm.Utc);
                break;
            case TimeKind.GeneralTime:
                writer.WriteTime(Asn1Tag.GeneralizedTime, Value, Asn1TimeForm.Generalized, 3);
                break;
            default: throw new Asn1Exception("CHOICE has no alternative.");
        }
    }

    public static Time Decode(Asn1Reader reader)
    {
        if (!reader.TryPeekTag(out var peeked)) throw new Asn1Exception("Empty CHOICE.");
        var value = new Time();
        if (peeked.MatchesIgnoreConstructed(Asn1Tag.UtcTime))
        {
            value.Kind = TimeKind.UtcTime;
            value.Value = reader.ReadTime(Asn1Tag.UtcTime, Asn1TimeForm.Utc);
        }
        else if (peeked.MatchesIgnoreConstructed(Asn1Tag.GeneralizedTime))
        {
            value.Kind = TimeKind.GeneralTime;
            value.Value = reader.ReadTime(Asn1Tag.GeneralizedTime, Asn1TimeForm.Generalized);
        }
        else throw new Asn1Exception("Unknown CHOICE alternative.");
        return value;
    }
}

